<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_role('finance_officer');
$user=current_user();$flashes=render_flashes();$currentPage='dashboard';$pageTitle='Finance Activity Dashboard';
require_once __DIR__.'/_helpers.php';
$conn=Database::getConnection();
$uid=(int)($user['id']??$user['user_id']??0);
if($uid<=0){http_response_code(403);exit('Invalid Finance Officer account.');}
$cfg=fo_config($conn);$first=trim((string)($user['first_name']??'Finance Officer'));
$stats=['attendance'=>0,'draft'=>0,'pending'=>0,'approved'=>0,'outstanding_count'=>0,'outstanding_amount'=>0.0,'overdue_count'=>0,'exceptions'=>0];
if(fo_has_table($conn,'finance_attendance_approved')){$r=$conn->query("SELECT COUNT(*) total FROM finance_attendance_approved WHERE approval_status='approved'");$stats['attendance']=(int)($r?$r->fetch_assoc()['total']??0:0);}
if(fo_has_table($conn,'stipend_schedules')){
 $s=$conn->prepare("SELECT SUM(status='draft') draft,SUM(status='awaiting_approval') pending,SUM(status='approved') approved,SUM(status='approved' AND period_end<CURDATE()) overdue_count,SUM(CASE WHEN status='approved' THEN total_amount ELSE 0 END) outstanding_amount,SUM(status='approved') outstanding_count,SUM(CASE WHEN status IN ('draft','awaiting_approval','approved') THEN exception_count ELSE 0 END) exceptions FROM stipend_schedules WHERE created_by=? AND status<>'superseded'");
 if($s){$s->bind_param('i',$uid);$s->execute();$row=$s->get_result()->fetch_assoc()?:[];$s->close();foreach($row as $k=>$v)if($v!==null)$stats[$k]=in_array($k,['outstanding_amount'],true)?(float)$v:(int)$v;}
}
$recent=[];if(fo_has_table($conn,'finance_activity_log')){$s=$conn->prepare("SELECT action,description,entity_type,entity_id,created_at FROM finance_activity_log WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 8");if($s){$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$recent[]=$x;$s->close();}}
$schedules=[];if(fo_has_table($conn,'stipend_schedules')){$s=$conn->prepare("SELECT id,schedule_reference,period_start,period_end,status,participant_count,total_amount,exception_count,created_at FROM stipend_schedules WHERE created_by=? AND status<>'superseded' ORDER BY created_at DESC LIMIT 5");if($s){$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$schedules[]=$x;$s->close();}}
require __DIR__.'/_layout_start.php';
?>
