<section class="fo-stats fo-stats--4"><article><i class="fas fa-calendar-check"></i><strong><?=number_format($stats['attendance'])?></strong><span>Approved Attendance Records</span></article><article><i class="fas fa-file-pen"></i><strong><?=number_format($stats['draft'])?></strong><span>Draft Schedules</span></article><article><i class="fas fa-hourglass-half"></i><strong><?=number_format($stats['pending'])?></strong><span>Awaiting Approval</span></article><article><i class="fas fa-circle-check"></i><strong><?=number_format($stats['approved'])?></strong><span>Approved Schedules</span></article></section>
<section class="fo-stats fo-stats--4 fo-stats--payments"><article class="fo-stat-alert"><i class="fas fa-money-bill-transfer"></i><strong><?=number_format($stats['outstanding_count'])?></strong><span>Schedules awaiting payment processing</span><a href="<?=url('finance/outstanding_payments.php')?>">Review list <i class="fas fa-arrow-right"></i></a></article><article class="fo-stat-alert"><i class="fas fa-wallet"></i><strong><?=e(fo_money($stats['outstanding_amount']))?></strong><span>Approved value not marked processed</span><a href="<?=url('finance/outstanding_payments.php')?>">View amounts <i class="fas fa-arrow-right"></i></a></article><article class="fo-stat-alert <?= $stats['overdue_count']>0?'fo-stat-alert--warning':'' ?>"><i class="fas fa-calendar-xmark"></i><strong><?=number_format($stats['overdue_count'])?></strong><span>Approved schedules past period end</span><a href="<?=url('finance/outstanding_payments.php?filter=overdue')?>">Review overdue <i class="fas fa-arrow-right"></i></a></article><article><i class="fas fa-triangle-exclamation"></i><strong><?=number_format($stats['exceptions'])?></strong><span>Exceptions in active schedules</span><a href="<?=url('finance/exceptions.php')?>">Resolve exceptions <i class="fas fa-arrow-right"></i></a></article></section>
<div class="fo-grid"><section class="fo-card"><div class="fo-card__header"><h3>Recent Stipend Schedules</h3><p>Latest schedules created by your account.</p></div><?php if(!$schedules):?><div class="fo-empty"><i class="fas fa-file-invoice-dollar"></i><strong>No schedules yet</strong><span>Prepare a schedule from approved attendance.</span></div><?php else:?><div class="fo-list"><?php foreach($schedules as $r):?><a href="<?=url('finance/schedule_view.php?id='.(int)$r['id'])?>"><div><strong><?=e($r['schedule_reference'])?></strong><span><?=e(fo_date($r['period_start']))?> – <?=e(fo_date($r['period_end']))?> · <?=e(fo_money($r['total_amount']))?> · <?=number_format((int)$r['participant_count'])?> participants</span></div><span class="fo-status fo-status--<?=e(fo_status_class($r['status']))?>"><?=e(fo_label($r['status']))?></span></a><?php endforeach;?></div><?php endif;?></section>
<section class="fo-card"><div class="fo-card__header"><h3>Finance Controls</h3><p>Keep payment preparation transparent and auditable.</p></div><div class="fo-principles"><div><i class="fas fa-calculator"></i><strong>Calculation basis</strong><span>Attendance minutes, rate and exceptions remain traceable.</span></div><div><i class="fas fa-user-shield"></i><strong>Maker/checker separation</strong><span>The schedule maker cannot approve their own schedule when enabled.</span></div><div><i class="fas fa-lock"></i><strong>Audit trail</strong><span>Recent finance actions are displayed below.</span></div></div></section></div>
<section class="fo-card fo-activity-card"><div class="fo-card__header fo-card__header--split"><div><h3>Recent Finance Activity</h3><p>Latest actions recorded for your account.</p></div><a class="fo-btn fo-btn--secondary" href="<?=url('finance/activity_log.php')?>">Full activity log <i class="fas fa-arrow-right"></i></a></div><?php if(!$recent):?><div class="fo-empty"><i class="fas fa-clock-rotate-left"></i><strong>No activity recorded yet</strong><span>Actions will appear here when they are logged.</span></div><?php else:?><div class="fo-table-wrap"><table><thead><tr><th>Action</th><th>Details</th><th>Reference</th><th>Date and time</th></tr></thead><tbody><?php foreach($recent as $a):?><tr><td><?=e(fo_label($a['action']))?></td><td><?=e($a['description'])?></td><td><?=e(($a['entity_type']??'')?fo_label($a['entity_type']).' #'.(int)$a['entity_id']:'—')?></td><td><?=e(fo_datetime($a['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<div class="fo-note"><i class="fas fa-circle-info"></i><span><strong>Payment-status note:</strong> this application records schedules as <em>approved</em> or <em>processed</em>; it does not currently store bank settlement or individual participant payment confirmations. The outstanding totals therefore show approved schedules not yet marked processed, not independently verified unpaid bank transactions.</span></div>

